import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import os from'node:os';import path from'node:path';import{CvMaxService}from'../src/service.mjs';import{recordVerifiedExperience}from'../src/experience.mjs';
function fixture(fn){return async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cvmax-service-'));const snapshot={url:'https://example.test/apply',documentEpoch:'doc1',fingerprint:'page1',fields:[{ref:'name',label:'姓名',semanticId:'name',value:'',type:'text'}],controls:[],canAdvance:false,completionVerifiable:false};let calls=[],requests=[];let browser=async(action,a)=>{calls.push(action);requests.push({action,args:structuredClone(a)});if(action==='observe')return structuredClone(snapshot);if(action==='act'){snapshot.fields[0].value=a.actionSpec.value;return{accepted:true}}return{stopped:true}};const config={file:path.join(dir,'state.json'),browser:(...a)=>browser(...a),attachments:{read(){return{filename:'resume.pdf',mime:'application/pdf',sha256:'a'.repeat(64),bytes:Buffer.from('resume')}},persistResume(_ref,id,revision){return{resource:`saved:${id}/${revision}.pdf`,sha256:'a'.repeat(64),size:6,mime:'application/pdf',scope:'resume'}}},allowedOrigins:['https://example.test']};let service=new CvMaxService(config);try{await fn({get service(){return service},restart(){service=new CvMaxService(config)},snapshot,calls,requests,setBrowser(fn){browser=fn}})}finally{fs.rmSync(dir,{recursive:true,force:true})}}}
const create=s=>s.create({clientRequestId:'one',targets:[{url:'https://example.test/apply',tabId:1}],facts:[{id:'name',value:'Synthetic Applicant',sourceRef:'synthetic:test'}]});
async function ready(s){let t=create(s);t=s.claim({taskId:t.taskId,expectedRevision:t.revision});return(await s.observe({taskId:t.taskId})).task}
const wait=()=>new Promise(r=>setTimeout(r,20));
test('configured services consume only public releases and upload value-free feedback',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cvmax-public-')),snapshot={url:'https://example.test/apply',documentEpoch:'doc-public',fields:[{ref:'name',label:'姓名',semanticId:'name',value:'',type:'text'}],controls:[],canAdvance:false,completionVerifiable:false},experiences={},training={snapshot:{...structuredClone(snapshot),fields:[{...snapshot.fields[0],value:'Training'}]},evidence:[{action:{kind:'fill',fieldRef:'name',semanticId:'name',semanticOrdinal:0,factId:'name',value:'Training'}}]};training.runId='one';recordVerifiedExperience(experiences,training,()=>true,['Training']);training.runId='two';recordVerifiedExperience(experiences,training,()=>true,['Training']);const bundle=Object.values(experiences)[0],candidates=[],feedback=[],registry={cachedBundles(){return{}},async getReleased(){return{releaseId:9,releaseVersion:1,status:'released',bundle}},async submitCandidate(value){candidates.push(value);return{status:'candidate'}},async submitFeedback(value){feedback.push(value);return{status:'released'}}};let browser=async(action,args)=>{if(action==='observe')return structuredClone(snapshot);if(action==='act'){snapshot.fields[0].value=args.actionSpec.value;return{accepted:true}}return{stopped:true}};try{const service=new CvMaxService({file:path.join(dir,'state.json'),browser,attachments:{read(){throw Error('unused')}},allowedOrigins:['https://example.test'],experienceRegistry:registry});let t=service.create({clientRequestId:'public-release',targets:[{url:snapshot.url,tabId:1}],facts:[{id:'name',value:'Private Applicant',sourceRef:'file:resume.pdf#page=1'}]});t=service.claim({taskId:t.taskId,expectedRevision:t.revision});let observed=await service.observe({taskId:t.taskId});assert.equal(observed.experience.releaseId,9);assert.equal(observed.experience.suggestedActions.length,1);await service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:observed.experience.suggestedActions});await wait();observed=await service.observe({taskId:t.taskId});service.finish({taskId:t.taskId,expectedRevision:observed.task.revision,outcome:'partial'});await service.drainRegistry();assert.equal(candidates.length,0);assert.equal(feedback.length,1);assert.equal(feedback[0].outcome,'verified');assert.equal(JSON.stringify(feedback).includes('Private Applicant'),false);assert.equal(service.health().publicExperience,'configured')}finally{fs.rmSync(dir,{recursive:true,force:true})}});
test('version 3 partial task evidence is backfilled once into field experience',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cvmax-migrate-')),file=path.join(dir,'state.json'),makeTask=(id,runId,value)=>({taskId:id,state:'finished',current:1,factSnapshot:{facts:[{id:'name',value,sourceRef:'synthetic:test'}]},applications:[{runId,outcome:'partial',snapshot:{url:`https://example.test/jobs/${id}/apply`,fields:[{ref:'name',label:'姓名',semanticId:'name',type:'text',value}],controls:[]},evidence:[{action:{kind:'fill',fieldRef:'name',semanticId:'name',semanticOrdinal:0,factId:'name',value},evidence:{accepted:true}}]}]});fs.writeFileSync(file,JSON.stringify({version:3,tasks:{one:makeTask('11111','run-one','First Private'),two:makeTask('22222','run-two','Second Private')},requests:{},experiences:{}}));try{const config={file,browser:async()=>({}),attachments:{read(){throw Error('unused')}},allowedOrigins:['https://example.test']};let service=new CvMaxService(config),stored=Object.values(service.store.data.experiences)[0];assert.equal(service.store.data.version,7);assert.equal(stored.status,'reusable');assert.equal(JSON.stringify(stored).includes('Private'),false);const before=JSON.stringify(stored);service=new CvMaxService(config);stored=Object.values(service.store.data.experiences)[0];assert.equal(JSON.stringify(stored),before)}finally{fs.rmSync(dir,{recursive:true,force:true})}});
test('health reports service and browser readiness without exposing a submit capability',fixture(async f=>{assert.deepEqual(f.service.health(),{service:'ready',browser:'disconnected',finalSubmitAllowed:false})}));
test('a staged client request hides fact values and create freezes it without agent retransmission',fixture(async f=>{const saved=f.service.request_save({clientRequestId:'staged-one',links:['https://example.test/apply'],facts:[{id:'name',value:'Private Applicant',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test',sha256:'a'.repeat(64),size:6,mime:'application/pdf'}});assert.deepEqual(saved.links,['https://example.test/apply']);assert.equal(saved.factCount,1);assert.equal(saved.hasAttachment,true);assert.equal(JSON.stringify(saved).includes('Private Applicant'),false);assert.equal(JSON.stringify(f.service.request_get({clientRequestId:'staged-one'})).includes('Private Applicant'),false);const target={url:'https://example.test/apply',tabId:1},task=f.service.create({clientRequestId:'staged-one',targets:[target]});assert.equal(f.service.task_context({taskId:task.taskId}).facts[0].value,'Private Applicant');assert.equal(task.factSnapshot.factCount,1);assert.throws(()=>f.service.create({clientRequestId:'staged-one',targets:[target],facts:[{id:'name',value:'Other',sourceRef:'user:answer'}]}),/staged_request_scope_conflict/)}));
test('staged request idempotency uses attachment identity instead of a temporary resource path',fixture(async f=>{const base={clientRequestId:'staged-retry',currentPage:true,facts:[],attachment:{resource:'test',sha256:'a'.repeat(64),size:6,mime:'application/pdf',expiresAt:1}},first=f.service.request_save(base),second=f.service.request_save({...base,attachment:{...base.attachment,resource:'another-temporary-path',expiresAt:2}});assert.deepEqual(second,first);assert.throws(()=>f.service.request_save({...base,facts:[{id:'city',value:'Beijing',sourceRef:'user:answer'}]}),/request_key_conflict/)}));
test('each saved resume is one isolated fact aggregate and tasks never borrow from another resume',fixture(async f=>{const attachment={resource:'test'},a=f.service.resume_save({saveRequestId:'save-a',name:'数据分析版',facts:[{id:'name',value:'Applicant A',sourceRef:'file:resume-a.pdf#page=1'}],attachment}),b=f.service.resume_save({saveRequestId:'save-b',name:'产品经理版',facts:[{id:'name',value:'Applicant B',sourceRef:'file:resume-b.pdf#page=1'},{id:'email',value:'b@example.test',sourceRef:'file:resume-b.pdf#page=1'}],attachment});const ta=f.service.create({clientRequestId:'resume-a-task',targets:[{url:'https://example.test/apply',tabId:1}],resume:{id:a.resumeId,revision:a.revision}}),tb=f.service.create({clientRequestId:'resume-b-task',targets:[{url:'https://example.test/apply',tabId:2}],resume:{id:b.resumeId,revision:b.revision}}),ca=f.service.task_context({taskId:ta.taskId}),cb=f.service.task_context({taskId:tb.taskId});assert.deepEqual(ca.facts.map(x=>[x.id,x.value]),[['name','Applicant A']]);assert.deepEqual(cb.facts.map(x=>[x.id,x.value]),[['name','Applicant B'],['email','b@example.test']]);assert.deepEqual(ta.factSnapshot.resumeFact,{id:a.resumeId,revision:1,name:'数据分析版'});assert.equal(JSON.stringify(f.service.resume_list()).includes('Applicant'),false)}));
test('a task freezes the selected resume revision while a later revision serves only new tasks',fixture(async f=>{const attachment={resource:'test'},v1=f.service.resume_save({saveRequestId:'save-v1',name:'技术版',facts:[{id:'name',value:'Version One',sourceRef:'file:resume.pdf#page=1'}],attachment}),oldTask=f.service.create({clientRequestId:'old-revision-task',targets:[{url:'https://example.test/apply',tabId:1}],resume:{id:v1.resumeId,revision:1}}),v2=f.service.resume_save({saveRequestId:'save-v2',resumeId:v1.resumeId,expectedRevision:1,name:'技术版',facts:[{id:'name',value:'Version Two',sourceRef:'user:resume-correction'}]}),newTask=f.service.create({clientRequestId:'new-revision-task',targets:[{url:'https://example.test/apply',tabId:2}],resume:{id:v2.resumeId,revision:2}});assert.equal(f.service.task_context({taskId:oldTask.taskId}).facts[0].value,'Version One');assert.equal(f.service.task_context({taskId:newTask.taskId}).facts[0].value,'Version Two');assert.throws(()=>f.service.create({clientRequestId:'stale-revision-task',targets:[{url:'https://example.test/apply',tabId:3}],resume:{id:v1.resumeId,revision:1}}),/revision_conflict/)}));
test('public task views and reports omit fact values and internal action values',fixture(async f=>{let t=await ready(f.service);await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();t=(await f.service.observe({taskId:t.taskId})).task;const view=f.service.status({taskId:t.taskId}),report=f.service.report({taskId:t.taskId});assert.deepEqual(view.factSnapshot,{id:f.service.get(t.taskId).factSnapshot.id,factCount:1,hasAttachment:false});assert.equal(JSON.stringify(view).includes('Synthetic Applicant'),false);assert.equal(JSON.stringify(report).includes('Synthetic Applicant'),false);assert.equal('strategies'in view.applications[0].budget,false);assert.deepEqual(report.history[0].evidence[0],{operationId:f.service.get(t.taskId).applications[0].operation.id,kind:'fill',fieldRef:'name',factId:'name',verified:true});const context=f.service.task_context({taskId:t.taskId});assert.equal(context.facts[0].value,'Synthetic Applicant')}));
test('service projects real field and section progress without exposing fact values',fixture(async f=>{let t=create(f.service);t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;const observing=f.requests.find(item=>item.action==='observe').args.progress;assert.equal(observing.phase,'observing');assert.equal(observing.fieldLabel,'检查页面字段');await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();const acting=f.requests.find(item=>item.action==='act').args.progress;assert.equal(acting.phase,'filling');assert.equal(acting.fieldLabel,'姓名');assert.equal(acting.sectionLabel,'基本信息');assert.equal(acting.targetRef,'name');assert.equal(acting.current,1);assert.equal(acting.total,1);assert.equal(JSON.stringify(acting).includes('Synthetic Applicant'),false);const projected=f.requests.filter(item=>item.action==='progress').at(-1).args.progress;assert.equal(projected.phase,'verifying');assert.equal(projected.verified,1);assert.equal(projected.lastConfirmed,'姓名');assert.equal(projected.finalSubmitAllowed,false)}));
