test('native resume parsing is preferred, verified by page change, and its values can be corrected',fixture(async f=>{f.snapshot.fields=[{ref:'name',label:'姓名',semanticId:'name',value:'',type:'text'},{ref:'resume',label:'上传简历后自动解析',semanticId:'resume',value:'',type:'file',nativeParseCandidate:true}];f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume',reason:'file_context'}],inProgress:false};f.snapshot.fingerprint='native-page';f.setBrowser(async(action,args)=>{if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){if(args.actionSpec.kind==='native_parse')return{accepted:true,scope:'native_parser_triggered_requires_new_observation'};f.snapshot.fields[0].value=args.actionSpec.value;return{accepted:true,value:args.actionSpec.value}}return{stopped:true}});let t=f.service.create({clientRequestId:'native-success',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Correct Name',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'native_parse',fieldRef:'resume'}]});await wait();t=f.service.status({taskId:t.taskId});assert.equal(t.state,'waiting_native_parse');assert.equal(t.applications[0].operation.state,'awaiting_verification');f.snapshot.fields[0].value='Wrong Name';t=(await f.service.observe({taskId:t.taskId})).task;assert.equal(t.state,'running');assert.deepEqual(t.applications[0].nativeParse,{state:'succeeded',reason:null,changedFieldCount:1});await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();assert.equal(f.snapshot.fields[0].value,'Correct Name');assert.equal(f.service.status({taskId:t.taskId}).applications[0].operation.state,'verified')}));
test('a parser revealed after upload reuses the retained resume and tolerates site defaults',fixture(async f=>{f.snapshot.fields=[{ref:'country',label:'手机号码',semanticId:'mobile',value:'+86',type:'search'},{ref:'identity',label:'个人证件',semanticId:'identity',value:'中国 - 居民身份证',type:'search',sensitive:true},{ref:'none',label:'没有实习经历',semanticId:null,value:'on',checked:true,type:'checkbox'},{ref:'name',label:'姓名',semanticId:'name',value:'',type:'text'},{ref:'resume',label:'简历附件',semanticId:'resume',value:'',receiptText:'resume.pdf 将简历内容解析到表单？解析并覆盖',type:'file',nativeParseCandidate:true}];f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume'}],inProgress:false};let sentAttachment='unset';f.setBrowser(async(action,args)=>{if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){sentAttachment=args.attachment;f.snapshot.fields[3].value='Parsed Name';return{accepted:true}}return{stopped:true}});let t=f.service.create({clientRequestId:'native-retained',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Parsed Name',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'native_parse',fieldRef:'resume'}]});await wait();assert.equal(sentAttachment,undefined);assert.equal(f.service.get(t.taskId).applications[0].operation.actions[0].reuseUploaded,true);t=(await f.service.observe({taskId:t.taskId})).task;assert.equal(t.applications[0].nativeParse.state,'succeeded')}));
test('native parser no-effect becomes an explicit autonomous-fill fallback without replay',fixture(async f=>{f.snapshot.fields.push({ref:'resume',label:'Parse resume',semanticId:'resume',value:'',type:'file',nativeParseCandidate:true});f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume'}],inProgress:false};f.setBrowser(async(action)=>action==='observe'?structuredClone(f.snapshot):{accepted:true});let t=f.service.create({clientRequestId:'native-fallback',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Synthetic Applicant',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'native_parse',fieldRef:'resume'}]});await wait();f.service.get(t.taskId).applications[0].operation.verifyUntil=new Date(0).toISOString();t=(await f.service.observe({taskId:t.taskId})).task;assert.equal(t.state,'running');assert.deepEqual(t.applications[0].nativeParse,{state:'failed',reason:'native_parse_no_effect',changedFieldCount:0});assert.equal(t.applications[0].operation.state,'failed')}));
test('native parse survives service restart through read-only reconciliation and is not replayed',fixture(async f=>{f.snapshot.fields.push({ref:'resume',label:'Parse resume',semanticId:'resume',value:'',type:'file',nativeParseCandidate:true});f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume'}],inProgress:false};let acts=0;f.setBrowser(async(action)=>{if(action==='act')acts++;return action==='observe'?structuredClone(f.snapshot):{accepted:true}});let t=f.service.create({clientRequestId:'native-restart',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Parsed Name',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'native_parse',fieldRef:'resume'}]});await wait();f.snapshot.fields[0].value='Parsed Name';f.restart();t=f.service.status({taskId:t.taskId});assert.equal(t.state,'needs_reconcile');assert.equal(t.applications[0].operation.state,'unknown');t=await f.service.reconcile({taskId:t.taskId});assert.equal(t.state,'running');assert.equal(t.applications[0].operation.state,'verified');assert.equal(t.applications[0].nativeParse.state,'succeeded');assert.equal(acts,1)}));
test('restart queues a task whose last operation was already verified',fixture(async f=>{let t=await ready(f.service);await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();assert.equal(f.service.status({taskId:t.taskId}).applications[0].operation.state,'verified');f.restart();t=f.service.status({taskId:t.taskId});assert.equal(t.state,'queued');assert.match(t.notice,/服务已恢复/);t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;assert.equal(t.state,'running');assert.equal(t.notice,undefined)}));
