test('pause/stop before dispatch blocks browser write and stopped task cannot resume',fixture(async f=>{let t=await ready(f.service);await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await f.service.control({taskId:t.taskId,kind:'stop'});await wait();assert.equal(f.calls.filter(c=>c==='act').length,0);f.restart();t=f.service.status({taskId:t.taskId});assert.equal(t.state,'cancelled');assert.throws(()=>f.service.resume({taskId:t.taskId,expectedRevision:t.revision}),/terminal/)}));
test('unknown in-flight effect survives stop/restart and prevents replay',fixture(async f=>{let t=await ready(f.service);f.setBrowser(async action=>{if(action==='act')throw Error('lost_ack');if(action==='observe')return structuredClone(f.snapshot);return{stopped:true}});await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();await f.service.control({taskId:t.taskId,kind:'stop'});f.restart();t=f.service.status({taskId:t.taskId});assert.equal(t.state,'cancelled');assert.equal(t.applications[0].operation.state,'unknown');assert.equal(t.applications[0].budget.actions,1)}));
