test('resume strategy is explicit and prevents field experience from racing the site parser',fixture(async f=>{
 f.snapshot.fields.push({ref:'resume',label:'上传简历并解析',semanticId:'resume',value:'',type:'file',nativeParseCandidate:true});
 f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume'}],inProgress:false};
 let t=f.service.create({clientRequestId:'resume-order',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Synthetic Applicant',sourceRef:'synthetic:test'}],attachment:{resource:'test'}});
 t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});
 const observed=await f.service.observe({taskId:t.taskId});
 assert.deepEqual(observed.resumeStrategy,{kind:'native_parse',fieldRef:'resume',isolated:true});
 await assert.rejects(f.service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]}),/native_resume_strategy_required/);
}));

test('a hidden parser requires one isolated upload before other field actions',fixture(async f=>{
 f.snapshot.fields.push({ref:'resume',label:'简历附件',semanticId:'resume',value:'',receiptText:'',type:'file',nativeParseCandidate:false});
 f.snapshot.nativeResumeParse={available:false,candidates:[],inProgress:false};
 let t=f.service.create({clientRequestId:'resume-upload-order',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Synthetic Applicant',sourceRef:'synthetic:test'}],attachment:{resource:'test'}});
 t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});
 const observed=await f.service.observe({taskId:t.taskId});
 assert.deepEqual(observed.resumeStrategy,{kind:'upload_then_reobserve',fieldRef:'resume',isolated:true});
 await assert.rejects(f.service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:[{kind:'upload',fieldRef:'resume'},{kind:'fill',fieldRef:'name',factId:'name'}]}),/isolated_resume_upload_required/);
}));

test('one service call executes and finishes an exact reusable page without another agent decision',fixture(async f=>{
 async function train(key,value){f.snapshot.fields[0].value='';let t=f.service.create({clientRequestId:key,targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value,sourceRef:'synthetic:test'}]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();t=(await f.service.observe({taskId:t.taskId})).task;f.service.finish({taskId:t.taskId,expectedRevision:t.revision,outcome:'partial'})}
 await train('fast-train-one','First');await train('fast-train-two','Second');f.snapshot.fields[0].value='';f.calls.length=0;let t=f.service.create({clientRequestId:'fast-known',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Third',sourceRef:'synthetic:test'}]});const result=await f.service.run_experience({taskId:t.taskId,expectedRevision:t.revision});assert.equal(result.path,'experience');assert.equal(result.outcome,'partial');assert.equal(result.actionCount,1);assert.equal(result.task.state,'finished');assert.equal(f.snapshot.fields[0].value,'Third');assert.equal(f.calls.filter(action=>action==='act').length,1);assert.equal(result.finalSubmitAllowed,false)
}));

test('experience execution returns a running adaptive handoff on a new or changed page',fixture(async f=>{const t=f.service.create({clientRequestId:'fast-cold',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Applicant',sourceRef:'synthetic:test'}]}),result=await f.service.run_experience({taskId:t.taskId,expectedRevision:t.revision});assert.equal(result.path,'adaptive');assert.equal(result.reason,'experience_not_reusable');assert.equal(result.task.state,'running');assert.equal(f.calls.includes('act'),false)}));

test('known-page execution lets the native parser run once and corrects its values from the same resume facts',fixture(async f=>{
 f.snapshot.fields.push({ref:'resume',label:'上传简历并解析',semanticId:'resume',value:'',receiptText:'',type:'file',nativeParseCandidate:true});f.snapshot.nativeResumeParse={available:true,candidates:[{fieldRef:'resume'}],inProgress:false};
 f.setBrowser(async(action,args)=>{f.calls.push(action);f.requests.push({action,args:structuredClone(args)});if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){if(args.actionSpec.kind==='native_parse'){f.snapshot.fields[0].value='网站误解析';f.snapshot.fields[1].value='resume.pdf';f.snapshot.fields[1].receiptText='resume.pdf';return{accepted:true}}f.snapshot.fields[0].value=args.actionSpec.value;return{accepted:true}}return{stopped:true}});
 async function train(key,value){f.snapshot.fields[0].value='';f.snapshot.fields[1].value='existing.pdf';f.snapshot.fields[1].receiptText='existing.pdf';let t=f.service.create({clientRequestId:key,targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value,sourceRef:'synthetic:test'}]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();t=(await f.service.observe({taskId:t.taskId})).task;f.service.finish({taskId:t.taskId,expectedRevision:t.revision,outcome:'partial'})}
 await train('parser-fast-one','First');await train('parser-fast-two','Second');f.snapshot.fields[0].value='';f.snapshot.fields[1].value='';f.snapshot.fields[1].receiptText='';f.calls.length=0;let t=f.service.create({clientRequestId:'parser-fast-known',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Resume Truth',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}});const result=await f.service.run_experience({taskId:t.taskId,expectedRevision:t.revision});assert.equal(result.path,'experience');assert.equal(result.task.state,'finished');assert.equal(f.snapshot.fields[0].value,'Resume Truth');assert.deepEqual(f.calls.filter(action=>action==='act').length,2);assert.equal(f.service.get(t.taskId).applications[0].nativeParse.state,'succeeded')
}));

test('known-page execution recognizes automatic parsing after upload and corrects it without an agent turn',fixture(async f=>{
 f.snapshot.fields.push({ref:'resume',label:'简历附件',semanticId:'resume',value:'',receiptText:'',type:'file',nativeParseCandidate:false});f.snapshot.nativeResumeParse={available:false,candidates:[],inProgress:false};
 f.setBrowser(async(action,args)=>{f.calls.push(action);f.requests.push({action,args:structuredClone(args)});if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){if(args.actionSpec.kind==='upload'){f.snapshot.fields[0].value='自动解析错误';f.snapshot.fields[1].value='resume.pdf';f.snapshot.fields[1].receiptText='resume.pdf';return{accepted:true}}f.snapshot.fields[0].value=args.actionSpec.value;return{accepted:true}}return{stopped:true}});
 async function train(key,value){f.snapshot.fields[0].value='';f.snapshot.fields[1].value='existing.pdf';f.snapshot.fields[1].receiptText='existing.pdf';let t=f.service.create({clientRequestId:key,targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value,sourceRef:'synthetic:test'}]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'fill',fieldRef:'name',factId:'name'}]});await wait();t=(await f.service.observe({taskId:t.taskId})).task;f.service.finish({taskId:t.taskId,expectedRevision:t.revision,outcome:'partial'})}
 await train('auto-fast-one','First');await train('auto-fast-two','Second');f.snapshot.fields[0].value='';f.snapshot.fields[1].value='';f.snapshot.fields[1].receiptText='';f.calls.length=0;const t=f.service.create({clientRequestId:'auto-fast-known',targets:[{url:f.snapshot.url,tabId:1}],facts:[{id:'name',value:'Resume Truth',sourceRef:'file:resume.pdf#page=1'}],attachment:{resource:'test'}}),result=await f.service.run_experience({taskId:t.taskId,expectedRevision:t.revision});assert.equal(result.path,'experience');assert.equal(result.task.state,'finished');assert.equal(f.snapshot.fields[0].value,'Resume Truth');assert.equal(f.calls.filter(action=>action==='act').length,2);const native=f.service.get(t.taskId).applications[0].nativeParse;assert.equal(native.state,'succeeded');assert.equal(native.reason,'automatic_after_upload')
}));

test('a retained matching resume receipt suppresses a duplicate experienced upload',fixture(async f=>{
 f.snapshot.fields=[{ref:'resume',label:'简历附件',semanticId:'resume',value:'',receiptText:'',type:'file'}];f.setBrowser(async(action,args)=>{if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){f.snapshot.fields[0].value='resume.pdf';f.snapshot.fields[0].receiptText='resume.pdf';return{accepted:true}}return{stopped:true}});
 async function train(key){f.snapshot.fields[0].value='';f.snapshot.fields[0].receiptText='';let t=f.service.create({clientRequestId:key,targets:[{url:f.snapshot.url,tabId:1}],facts:[],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});t=(await f.service.observe({taskId:t.taskId})).task;await f.service.apply({taskId:t.taskId,expectedRevision:t.revision,actions:[{kind:'upload',fieldRef:'resume'}]});await wait();t=(await f.service.observe({taskId:t.taskId})).task;f.service.finish({taskId:t.taskId,expectedRevision:t.revision,outcome:'partial'})}
 await train('upload-one');await train('upload-two');let t=f.service.create({clientRequestId:'upload-preserved',targets:[{url:f.snapshot.url,tabId:1}],facts:[],attachment:{resource:'test'}});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});const observed=await f.service.observe({taskId:t.taskId});assert.equal(observed.experience.match,'exact');assert.deepEqual(observed.experience.suggestedActions,[]);assert.equal(observed.experience.preserved.length,1)
}));

test('a zero-field detail page cannot finish and a safe start control hands off to the application URL',fixture(async f=>{
 const detail='https://example.test/jobs/12345',apply='https://example.test/jobs/12345/apply';
 f.snapshot.url=detail;f.snapshot.formStage='detail';f.snapshot.fields=[];f.snapshot.controls=[{ref:'start',label:'立即申请',kind:'start',safe:true}];f.snapshot.canAdvance=false;f.snapshot.completionVerifiable=false;
 f.setBrowser(async(action,args)=>{if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){assert.equal(args.actionSpec.kind,'start');f.snapshot.url=apply;f.snapshot.formStage='apply';f.snapshot.documentEpoch='application-document';f.snapshot.fields=[{ref:'name',label:'姓名',semanticId:'name',value:'',type:'text'}];f.snapshot.controls=[];return{accepted:true,url:apply,tabId:2,documentEpoch:'detail-document'}}return{stopped:true}});
 let t=f.service.create({clientRequestId:'detail-start',targets:[{url:detail,tabId:1}],facts:[{id:'name',value:'Synthetic Applicant',sourceRef:'synthetic:test'}]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});let observed=await f.service.observe({taskId:t.taskId});
 assert.throws(()=>f.service.finish({taskId:t.taskId,expectedRevision:observed.task.revision,outcome:'partial'}),/application_form_not_observed/);
 await f.service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:[{kind:'start',controlRef:'start'}]});await wait();observed=await f.service.observe({taskId:t.taskId});
 assert.equal(observed.task.currentApplication.url,apply);assert.equal(observed.task.applications[0].tabId,2);assert.equal(observed.snapshot.formStage,'apply');assert.equal(observed.task.applications[0].operation.state,'verified');
}));

test('a verified start click with no page effect stays retryable within the page budget',fixture(async f=>{
 const detail='https://example.test/jobs/slow-start';
 f.snapshot.url=detail;f.snapshot.formStage='detail';f.snapshot.fields=[];f.snapshot.controls=[{ref:'start',label:'立即投递',kind:'start',safe:true}];f.snapshot.canAdvance=false;f.snapshot.completionVerifiable=false;
 f.setBrowser(async(action,args)=>action==='observe'?structuredClone(f.snapshot):action==='act'?{accepted:true,url:detail,documentEpoch:f.snapshot.documentEpoch}:{stopped:true});
 let t=f.service.create({clientRequestId:'detail-start-retry',targets:[{url:detail,tabId:1}],facts:[]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});let observed=await f.service.observe({taskId:t.taskId});
 await f.service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:[{kind:'start',controlRef:'start'}]});await wait();observed=await f.service.observe({taskId:t.taskId});
 assert.equal(observed.task.state,'running');assert.equal(observed.task.applications[0].operation.state,'failed');assert.equal(observed.task.applications[0].operation.error,'application_start_no_effect');assert.equal(observed.task.applications[0].budget.replanCount,1);
}));

test('a same-document prerequisite modal verifies an application start',fixture(async f=>{
 const detail='https://example.test/jobs/modal-start';
 f.snapshot.url=detail;f.snapshot.pageState='normal';f.snapshot.formStage='detail';f.snapshot.fields=[];f.snapshot.controls=[{ref:'start',label:'立即投递',kind:'start',safe:true}];f.snapshot.canAdvance=false;f.snapshot.completionVerifiable=false;
 f.setBrowser(async(action,args)=>{if(action==='observe')return structuredClone(f.snapshot);if(action==='act'){f.snapshot.pageState='resume_prerequisite';f.snapshot.controls=[{ref:'edit',label:'编辑',kind:'start',safe:true}];return{accepted:true,url:detail,documentEpoch:f.snapshot.documentEpoch}}return{stopped:true}});
 let t=f.service.create({clientRequestId:'modal-start',targets:[{url:detail,tabId:1}],facts:[]});t=f.service.claim({taskId:t.taskId,expectedRevision:t.revision});let observed=await f.service.observe({taskId:t.taskId});
 await f.service.apply({taskId:t.taskId,expectedRevision:observed.task.revision,actions:[{kind:'start',controlRef:'start'}]});await wait();observed=await f.service.observe({taskId:t.taskId});
 assert.equal(observed.task.state,'running');assert.equal(observed.task.applications[0].operation.state,'verified');assert.equal(observed.snapshot.pageState,'resume_prerequisite');
}));
